import{_ as s,O as a,o as i,c as r,a as o,i as n,f as d}from"./chunks/framework.fmIt2z2h.js";const f=JSON.parse('{"title":"附录D　领域解释与应用图谱","description":"","frontmatter":{"title":"附录D　领域解释与应用图谱","xkChars":105,"xkLessons":{"intro-20-appendix-d":{"title":"附录D　领域解释与应用图谱","lead":"这份图谱是从领域问题进入框架的导航，不是把三十二门知识压成同一种答案。每一领域仍须用适合自己的材料回答问题，同一条来源被多个领域引用也不会变成多次独立验证。","explanation":["原文定位：第4525—4528行；原文锚点 part_20；短引文：‘各领域不承担互相验证的责任。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","附录D导语规定先后次序：先保留领域原来的问题，再连接正文中适用的表示、证据、规范与行动边界。保留问题意味着不能把经济、法律、照护、历史或艺术的问题一律换成圈层是否升级。领域可能主要需要解释机制、阐明意义、论证规范、核查程序或完成形式证明；任务不同，合适材料与终点也不同。","三十二个领域是图谱的组织范围，不是已经完成三十二次独立经验验证的计数。本节“承接既有研究”是作者对来源脉络的说明；若要进一步断言某项研究的真实历史采纳、数据或结论，仍须取得对应原研究及版本。本讲据可访问的当前原文解释连接方式，不把研究入口编号当作已读完其背后全文。","连接正文四个方面各有职责。表示说明以什么对象、变量和尺度表达问题；证据说明材料怎样支持具体主张；规范公开保护与价值前提；行动边界限定谁能做什么以及如何停止补救。这些层面相互关联，但表示清楚不证明事实，证据充分不消除规范分歧，价值理由也不产生现实授权。","各领域不承担互相验证责任，意指不能用“物理中有反馈”证明组织的反馈机制已成立，也不能用“某制度研究采用类似词”证明心理领域的假设。领域材料能够经明确桥接相互补充，但支持仍来自各自可检的对象、方法和条件，不能从同名或共同归入图谱取得证据。","多个研究引用同一原作、数据或案例时，要保留相关来源关系。同一数据的不同分析可以提供稳健性检查、不同问题答案或相互争论，未必毫无增量；但不能按论文或章节数量累加为独立样本与独立复现。真正独立性要看数据生成、测量、对象与推断关系，不能仅看作者署名或页面地址。","阅读图谱时可以逐节问：本领域具体想解释什么；所用领域方法能答到哪一步；框架新增了哪项区分；哪些内容仍待来源核验；是否出现规范或行动越级。图谱本身是问题组织，不是对读者设置额外准入门槛；足够好的领域说明可以直接保留，不必先翻译成整套术语。"],"distinctions":[{"leftTitle":"领域图谱","leftText":"组织问题与可用连接的导航。","rightTitle":"独立验证清单","rightText":"需要分别有适用实证与来源关系，不能由三十二领域数量推出。"},{"leftTitle":"互相补充","leftText":"不同材料回答不同局部问题，并核连接。","rightTitle":"互相担保","rightText":"某领域成立就替另一领域作证，是本节排除的跳跃。"},{"leftTitle":"同数据多分析","leftText":"可能增加稳健性或新问题理解。","rightTitle":"独立复现","rightText":"需核材料生成与依赖，不能按引用数累计。"}],"boundaries":["本导语为导航与证据关系原则，不强塞与其无关的历史成效案例。","研究入口编号不是所指全部研究全文已经取得或核验的证明。","领域方法可以独立完成任务，不须经统一框架重新认证才能成为知识。","同源分析不必毫无价值，但不能伪装为多个独立样本。"],"questions":["图谱先保留领域问题的作用是什么？","同一案例被五章引用，是否等于五次复现？","领域结论充分时还必须增加圈层吗？"],"diagramPath":"/reading-assets/S-D-01/figures/intro-20-appendix-d.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"intro-20-appendix-d","start_line":4525,"end_line":4528,"startLine":4525,"endLine":4528}],"outputId":"intro-20-appendix-d","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["以领域实际问题确定本节任务，而非先选框架词语。","分别连接适用的表示、证据、规范及行动条件。","对跨领域借用说明桥接与不可迁移部分。","追踪多个引用是否共享原作、数据或案例，避免重复认证。","保留领域独立答案及具体未决，不以导航覆盖率证明现实可靠。"],"teachingExamples":[{"title":"教学构造：三处引用仍可能一条证据链","text":"假想经济、组织、技术三章都引用同一机构报告中的同一统计表。它们可分别分析资源、职责和工具，却不能宣布三门领域独立复现了同一现实效应。应在来源图中把三条引用连回同一张表，并分别标明各章新增的推断。","assumptions":"章节、报告和表格均为教学构造。","boundary":"没有估计现实证据独立度或有效样本量。"},{"title":"教学构造：不同任务各有终点","text":"假想读者只问一段史料的用词含义，领域文本解释已有依据；可以在准确解释和限制处结束，不必再构造一张组织行动图。若读者要据此采取高影响决定，则需额外事实、规范与授权材料。","assumptions":"阅读任务为构造。","boundary":"普通理解和现实行动的责任不同，但不能靠改称理解逃避实际高影响用途。"}],"counterexamples":[{"identity":"constructed_boundary","text":"图谱有三十二领域，因此框架已获三十二次独立验证。","effect":"领域数量是组织范围，独立验证须查具体材料与依赖。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"同源研究不能独立验证，所以所有后续分析都没有价值。","effect":"它们可回答新问题或检验稳健性，只是不能冒称独立样本。","sourceIds":["theory"]}],"questionAnswers":[{"question":"图谱先保留领域问题的作用是什么？","answer":"避免框架术语提前决定答案，允许领域方法按自己任务完成说明。","basis":"本节原文及上述公开推导"},{"question":"同一案例被五章引用，是否等于五次复现？","answer":"不是，须追踪共同来源和各章新增推断；重复引用不生成独立材料。","basis":"本节原文及上述公开推导"},{"question":"领域结论充分时还必须增加圈层吗？","answer":"不必；框架可仅做来源与边界检查，不能为统一表达增加无用负担。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-01/figures/intro-20-appendix-d.png","alt":"先保留领域问题，机制／意义／规范，程序／形式等任务；连接适用正文，表示／证据，规范／行动边界；保留领域独立答案，不强制术语统一；同一原作／数据／案例，可被多节引用；来源关系仍相关，不按引用数累计复现；跨域结论另核桥接，导航覆盖≠现实验证。作者依附录D导语绘制；三十二领域为导航范围，不是独立实证数量。","caption":"作者依附录D导语绘制；三十二领域为导航范围，不是独立实证数量。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。点击多章引用时高亮共同来源，切换不同领域问题显示不同证据职责，不生成虚构研究结果。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"导语规定导航顺序与证据依赖，不提出可单独用历史案例验证的领域效应；以明确教学依赖图解释，不虚构领域验证史。"},"openQuestions":["导语所称既有研究的逐项历史采纳需相应原研究记录；本文不以目录代替全文核验。"],"taskId":"S-D-01","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4525—4544行；每节精确范围见sourceRefs","claim_support":["intro-20-appendix-d：术语、合同、论证责任和原文边界；不据此认证经验事实","D.01：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"theory-cross","title":"Xikari任务、论证身份与来源契约","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§1.3—1.10第99—181行；§2.2—2.7.1第239—355行","claim_support":["领域任务独立性、命题分型、类比与来源关系及答案上限"],"limits":["理论说明不充当外部经验支持。"],"access_status":"read"},{"id":"w3c-em2","title":"WCAG Evaluation Methodology (WCAG-EM) 2.0","url":"https://www.w3.org/TR/2026/NOTE-wcag-em-2-20260723/","source_type":"primary","version_or_date":"W3C Group Note 2026-07-23","locator":"文首日期/Status；Relation to WCAG2 conformance claims第1—3段；Involving users正文段","claim_support":["样本评价不能直接声明整个网站符合；用户参与有助发现专家难发现的障碍"],"limits":["指导性Group Note而非新增规范；不证明具体实施或本框架历史采用。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-01/lecture.md","sourcesPath":"/reading-assets/S-D-01/sources.json","sourceSlicePath":"/reading-assets/S-D-01/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-01/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/index.md","filePath":"theory/appendix-d/index.md"}'),p={name:"theory/appendix-d/index.md"};function c(l,e,u,_,m,h){const t=a("SectionLesson");return i(),r("div",null,[e[0]||(e[0]=o('<div class="theory-source"><p><a id="part_20"></a></p><h1 id="part-title-20" tabindex="-1"><span class="xk-part">附录D<span class="xk-part__gap">　</span></span>领域解释与应用图谱 <a class="header-anchor" href="#part-title-20" aria-label="Permalink to &quot;附录D　领域解释与应用图谱 {#part-title-20}&quot;">​</a></h1><p>本图谱承接32个领域的既有研究。每节先保留领域问题，再连接正文中适用的表示、证据、规范和行动边界。各领域不承担互相验证的责任；多个研究引用同一原作、数据或案例时，仍是一条相互关联的证据链。</p></div>',1)),n(t,{section:"intro-20-appendix-d"}),e[1]||(e[1]=d("div",{class:"theory-source"},null,-1))])}const g=s(p,[["render",c]]);expor